head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.contnId;
scwin.gLdMktTp = js_market;
scwin.vScrenID = "ULDSTF30300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  지식구분 셋팅
    dts_KnowlgTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=LD_KNOWLG_TP_CD";
    dts_KnowlgTp.Reset();
};
scwin.fn_Init = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");

    //2021-03-12 KBoY Deafult 에 2020-01-01 넣음
    //	edt_SDate.text = cGetMinusMonth(vCurDate.substring(0,4), vCurDate.substring(4,6), vCurDate.substring(6,8), 1); 	// 한달전 날짜

    edt_EDate.setValue(vCurDate);
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        $c.stf.showObj(panel_mkt, false);
    }
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var KeyWord = $c.cp.valueOfIndex(keyword, "VALUE", keyword.getSelectedIndex());
    var Condition = condition1.getValue();
    //var UserId = condition2.value;
    var SDate = edt_SDate.getValue();
    var EDate = edt_EDate.getValue();
    url = "/ShareRoom.do?method=listShareRoom&KeyWord=" + KeyWord + "&Condition=" + Condition + "&ImptContnYn=" + scwin.getChkValue(chb_impt_contn_yn) + "&CreatlocTpCd=" + $c.stf.getObjectValue(rdo_creatloc_tp) + "&KnowlgTpCd=" + $c.stf.getObjectValue(cmb_knowlg_tp) + "&SDate=" + SDate + "&EDate=" + EDate + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_listShareRoom.DataID = encodeURI(url);
    dts_listShareRoom.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setContnId = function(obj) {
    if (scwin.contnId != "input") {
        scwin.contnId = dts_listShareRoom.getCellData(eval(obj), "CONTN_ID");
    }
};
scwin.fn_getContnId = function() {
    return scwin.contnId;
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == 'TITLE') {
        scwin.fn_setContnId(row);
        await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30301.gfm", "보고및자료공유방 수정", 200, 100, 770, 575 + 40, "window");
        scwin.fn_list_sync();
    }
};
scwin.btn_Input_onclick = async function() {
    scwin.contnId = "input";
    await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30301.gfm", "지식공유방 등록", 200, 100, 770, 575 + 40, "window");
    scwin.contnId = "";
    scwin.fn_list_sync();
};
scwin.dts_listShareRoom_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_listShareRoom.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_listShareRoom_OnLoadError = function() {
    $c.cm.CloseWin('', grd_Grid);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "지식공유방", "", "2");
};
scwin.rdo_creatloc_tp_OnSelChange = function() {
    if ($c.stf.getObjectValue(rdo_creatloc_tp) != '99') {
        dts_KnowlgTp.UseFilter = true;
        dts_KnowlgTp.Filter();
        cmb_knowlg_tp.trigger("onclick");
    } else {
        dts_KnowlgTp.UseFilter = true;
        dts_KnowlgTp.Filter();
        dts_KnowlgTp.sort('+VALUE', 0);
        //dts_KnowlgTp.sort(); // W-Craft 주석처리 
        cmb_knowlg_tp.trigger("onclick");
    }
};
scwin.dts_KnowlgTp_OnFilter = function(row) {
    //alert(dts_KnowlgTp.NameValue(row, "value").substr(0,1) );
    //  생성처에 따른 지식구분을 가져온다.
    if ($c.stf.getObjectValue(rdo_creatloc_tp) == '01') {
        if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == 'A' ||
            dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == '') {
            return true;
        } else {
            return false;
        }
    } else if ($c.stf.getObjectValue(rdo_creatloc_tp) == '02') {
        if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == 'B' ||
            dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == '') {
            return true;
        } else {
            return false;
        }
    } else if ($c.stf.getObjectValue(rdo_creatloc_tp) == '99') {
        return true;
    } else {
        return false;
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_Init();
    scwin.fn_list_sync();
};
